<script>export let data; export let inspect=()=>{}; const val=(v)=>v.value_state==='known'?`${v.dimension}: ${typeof v.value==='object'?JSON.stringify(v.value):String(v.value)}`:`${v.dimension}: ${v.value_state}`;</script>
<div class="renderer-stack" data-renderer="state-flow">
  {#if data.semantics==='actionability-is-not-execution-authority'}<div class="safety-note"><strong>Lecture seulement.</strong> L’actionabilité décrit des conditions; elle n’accorde aucune permission d’exécution.</div>{/if}
  {#each data.records || [] as record}<section class="renderer-card"><button class="renderer-title" on:click={()=>record.entity?.id&&inspect(record.entity.id)}>{record.entity?.label||record.assertionRef}</button><small>{record.recordRole||record.status} · {record.relationLabel}</small>{#if record.actionability?.mode}<p>Actionabilité: <b>{record.actionability.mode}</b>{record.actionability.requires_human_validation?' · validation humaine requise':''}</p>{/if}{#if record.valuations?.length}<div class="record-tags">{#each record.valuations.slice(0,6) as v}<span>{val(v)}</span>{/each}</div>{/if}</section>{:else}<p class="empty-renderer">Aucun état visible.</p>{/each}
</div>
